import math
L1=2.5;C=1.3;L2=3.6
X=0.0;Y=0.0;TH=0.0
last_t=None
grid={}
phase='REV'
fx=0.0;fy=0.0;fdist=2.0
lastp=-10
was_pinned=True
last_dir=1
fsteer=0.0

def clamp(v,a,b):
    return max(a,min(b,v))

def mid(rel,s0,s1):
    wl=None;wr=None
    for (a,w) in rel:
        if a<s0 or a>s1 or abs(w)>6.5: continue
        if w>0:
            if wl is None or w<wl: wl=w
        else:
            if wr is None or w>wr: wr=w
    if wl is not None and wr is not None: return (wl+wr)/2.0,wl,wr
    if wl is not None: return wl-2.6,wl,wr
    if wr is not None: return wr+2.6,wl,wr
    return 0.0,wl,wr

def control(obs):
    global X,Y,TH,last_t,phase,fx,fy,fdist,lastp,was_pinned,last_dir,fsteer
    t=obs['t']
    mo=obs['motion']; v=mo['v_mps']; st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        X+=v*math.cos(TH)*d; Y+=v*math.sin(TH)*d; TH+=v/L1*math.tan(st)*d
    last_t=t
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for b,dd in vw.get('walls',[]):
            if dd>14: continue
            br=math.radians(b); px=o[0]+dd*math.cos(br); py=o[1]+dd*math.sin(br)
            wx=X+c*px-s*py; wy=Y+s*px+c*py
            grid[(round(wx*4),round(wy*4))]=(wx,wy)
    rig=obs['rig']; hz=rig['hitch']; rr=rig['trailer_rear']
    RX=X+c*rr[0]-s*rr[1]; RY=Y+s*rr[0]+c*rr[1]
    thr=TH+math.atan2(rr[1]-hz[1],rr[0]-hz[0])
    ux=math.cos(thr); uy=math.sin(thr)
    hitch=obs['hitch_deg']
    look=-165 if (t%4.5)<2.5 else 64
    rel=[]
    for (wx,wy) in grid.values():
        dx=wx-RX; dy=wy-RY
        if dx*dx+dy*dy<81:
            rel.append((dx*ux+dy*uy,dx*uy-dy*ux))
    m1,l1,r1=mid(rel,-0.5,3.0)
    m2,l2,r2=mid(rel,3.0,7.0)
    alpha=0.4*math.degrees(math.atan2(m1,1.5))+0.6*math.degrees(math.atan2(m2,5.0))
    hd=clamp(1.0*alpha,-35,35)
    rem=obs['progress']['remaining']
    if rem<6: hd=clamp(hd,-8,8)
    pinned=(obs.get('status')=='PINNED')
    if pinned and not was_pinned:
        if last_dir<0:
            phase='FWD'; fx=X; fy=Y; fdist=2.0
            lp=0;rp=0
            for (wx,wy) in grid.values():
                dx=wx-X; dy=wy-Y
                px=dx*c+dy*s; py=-dx*s+dy*c
                if 0.5<px<6 and abs(py)<4:
                    if py>0: lp+=1.0/(py+0.3)
                    else: rp+=1.0/(-py+0.3)
            fsteer=-12.0 if lp>rp else 12.0
        else:
            phase='REV'
    was_pinned=pinned
    if abs(hitch)>55 and phase=='REV':
        phase='FWD'; fx=X; fy=Y; fdist=3.0; fsteer=0.0
    if phase=='FWD':
        if math.hypot(X-fx,Y-fy)>fdist:
            phase='REV'
        else:
            last_dir=1
            return (clamp(fsteer-0.3*hitch,-30,30),0.6,look)
    h=math.radians(hd)
    deq=math.degrees(math.atan(L1*math.sin(h)/(L2+C*math.cos(h))))
    steer=clamp(deq+2.0*(hitch-hd),-45,45)
    sp=-0.5
    if abs(hitch-hd)>15 or rem<6: sp=-0.35
    last_dir=-1
    if t-lastp>3:
        lastp=t
        print('t%.0f %s h%.0f hd%.0f m1%.1f m2%.1f L1%s R1%s L2%s R2%s n%d rem%.1f'%(t,phase,hitch,hd,m1,m2,str(l1 and round(l1,1)),str(r1 and round(r1,1)),str(l2 and round(l2,1)),str(r2 and round(r2,1)),len(rel),rem))
    return (steer,sp,look)

