import math
L1=2.5;C=1.3;L2=3.6
X=0.0;Y=0.0;TH=0.0
last_t=None
grid={}
phase='FWD'
fx=0.0;fy=0.0;fmin=3.5;fmax=8.0
lastp=-10
nsw=0
woke=False

def clamp(v,a,b):
    return max(a,min(b,v))

def fit(pts):
    n=len(pts)
    if n<3: return None
    mx=sum(p[0] for p in pts)/n; my=sum(p[1] for p in pts)/n
    sxx=sum((p[0]-mx)**2 for p in pts); sxy=sum((p[0]-mx)*(p[1]-my) for p in pts)
    if sxx<0.5: return (my,0.0)
    b=clamp(sxy/sxx,-0.7,0.7)
    return (my-b*mx,b)

def mid(rel,s0,s1):
    wl=None;wr=None
    for (a,w) in rel:
        if a<s0 or a>s1 or abs(w)>6.5: continue
        if w>0:
            if wl is None or w<wl: wl=w
        else:
            if wr is None or w>wr: wr=w
    if wl is not None and wr is not None: return (wl+wr)/2.0
    if wl is not None: return wl-2.6
    if wr is not None: return wr+2.6
    return 0.0

def control(obs):
    global X,Y,TH,last_t,phase,fx,fy,fmin,fmax,lastp,nsw,woke
    t=obs['t']
    mo=obs['motion']; v=mo['v_mps']; st=math.radians(obs['steer_deg'])
    if last_t is not None:
        d=t-last_t
        X+=v*math.cos(TH)*d; Y+=v*math.sin(TH)*d; TH+=v/L1*math.tan(st)*d
    last_t=t
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for b,dd in vw.get('walls',[]):
            if dd>14: continue
            br=math.radians(b); px=o[0]+dd*math.cos(br); py=o[1]+dd*math.sin(br)
            wx=X+c*px-s*py; wy=Y+s*px+c*py
            grid[(round(wx*4),round(wy*4))]=(wx,wy)
    V=[]
    for (wx,wy) in grid.values():
        ex=wx-X; ey=wy-Y
        if ex*ex+ey*ey<144: V.append((ex*c+ey*s,-ex*s+ey*c))
    rig=obs['rig']; hz=rig['hitch']; rr=rig['trailer_rear']
    vf=rig.get('vehicle_front',2.9)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    hw=rig.get('vehicle_half_width',1.15) or 1.15
    thw=rig.get('trailer_half_width',1.2) or 1.2
    rearx=vf-3.9
    tl=math.hypot(rr[0]-hz[0],rr[1]-hz[1]) or 5.0
    u0=(rr[0]-hz[0])/tl; u1=(rr[1]-hz[1])/tl; n0=-u1; n1=u0
    hitch=obs['hitch_deg']
    rem=obs['progress']['remaining']
    def blockedR():
        for (x,y) in V:
            if rearx-0.25<x<0.8 and abs(y)<hw+0.2: return 'tractor'
            a=(x-hz[0])*u0+(y-hz[1])*u1; b=(x-hz[0])*n0+(y-hz[1])*n1
            if 0.2<a<tl+0.4 and abs(b)<thw+(0.35 if a>tl-1.5 else 0.2): return 'trailer'
        return None
    def blockedF():
        for (x,y) in V:
            if 0.0<x<vf+0.35 and abs(y)<hw+0.25: return 'front'
        return None
    if phase=='FWD':
        look=0
    else:
        look=160 if (t%6.0)<3.0 else -160
    if phase=='STOP':
        return (0.0,0.0,look)
    if phase=='FWD':
        Lp=[(x,y) for (x,y) in V if -1.5<x<7 and 0.3<y<5.5]
        Rp=[(x,y) for (x,y) in V if -1.5<x<7 and -5.5<y<-0.3]
        fl=fit(Lp); fr=fit(Rp)
        ps=[]
        if fl: ps.append(math.atan(fl[1]))
        if fr: ps.append(math.atan(fr[1]))
        hrel=-sum(ps)/len(ps) if ps else 0.0
        if fl and fr:
