import math
M={}
st={'x':0.0,'y':0.0,'th':0.0,'last_t':None,'phase':'rev','alpha':None,'bay':None,'look':165,'look_t':0.0,'pr':0.0}
L1=1.25
def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def clamp(v,a,b):
    return max(a,min(b,v))
def ff(phi):
    p=math.radians(phi)
    return math.degrees(math.atan(L1*math.sin(p)/(0.85+0.3*math.cos(p))))
def tw(px,py):
    c=math.cos(st['th']);s=math.sin(st['th'])
    return st['x']+px*c-py*s, st['y']+px*s+py*c
def control(obs):
    t=obs['t']
    mo=obs['motion']; v=mo['v_mps']; sd=obs['steer_deg']
    if st['last_t'] is not None:
        h=t-st['last_t']
        if 0<h<1:
            th=st['th']
            st['x']+=v*math.cos(th)*h; st['y']+=v*math.sin(th)*h
            st['th']=wrap(th+v*math.tan(math.radians(sd))/L1*h)
    st['last_t']=t
    rig=obs['rig']
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]) or []:
                px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
                wx,wy=tw(px,py)
                M[(round(wx*10),round(wy*10))]=(wx,wy)
        except Exception:
            pass
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('dist_m') is not None:
            ex,ey=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
            bx,by=tw(ex+d*math.cos(b),ey+d*math.sin(b))
            w=clamp(0.6/max(d,1.0),0.05,0.5)
            if st['bay'] is None: st['bay']=(bx,by)
            else: st['bay']=(st['bay'][0]+w*(bx-st['bay'][0]),st['bay'][1]+w*(by-st['bay'][1]))
    except Exception:
        pass
    hitch=obs['hitch_deg']
    # head
    if t-st['look_t']>4.0:
        st['look']=-st['look']; st['look_t']=t
    look=st['look']
    status=obs.get('status')
    if st['phase']=='fwd':
        if abs(hitch)<12:
            st['phase']='rev'
        else:
            return {'steer_deg':0.0,'speed_mps':0.5,'look_deg':look}
    if abs(hitch)>52 or status=='JACKKNIFED':
        st['phase']='fwd'
        print('fwd shunt t=%.1f hitch=%.1f'%(t,hitch))
        return {'steer_deg':0.0,'speed_mps':0.5,'look_deg':look}
    rx,ry=rig['trailer_rear']
    Rx,Ry=tw(rx,ry)
    psi=st['th']+math.radians(rig['trailer_heading_deg'])
    bd=wrap(psi+math.pi)
    Ax,Ay=Rx-0.45*math.cos(bd),Ry-0.45*math.sin(bd)
    alpha=None; info=''
    bay=st['bay']
    if bay is not None:
        db=math.hypot(bay[0]-Ax,bay[1]-Ay)
        if db<6.0:
            if db>0.6:
                alpha=math.atan2(bay[1]-Ay,bay[0]-Ax)
            else:
                alpha=st['alpha'] if st['alpha'] is not None else bd
