st={'x':0.0,'y':0.0,'th':0.0,'lt':None,'ph':'fwd','fo':0.0,'od':0.0,'bay':[-2.4,7.6],'pr':0.0}
L1=1.25
def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def clamp(v,a,b):
    return max(a,min(b,v))
def ff(phi):
    p=math.radians(phi)
    return math.degrees(math.atan(L1*math.sin(p)/(0.85+0.3*math.cos(p))))
def tw(px,py):
    c=math.cos(st['th']);s=math.sin(st['th'])
    return st['x']+px*c-py*s, st['y']+px*s+py*c
def boxd(a,b,a0,a1,hw):
    da=max(a0-a,0.0,a-a1); db=max(abs(b)-hw,0.0)
    return math.hypot(da,db)
def lookpt(path,P,la):
    best=None;acc=0.0
    for i in range(len(path)-1):
        x0,y0=path[i];x1,y1=path[i+1]
        dx=x1-x0;dy=y1-y0;L=math.hypot(dx,dy) or 1e-6
        u=clamp(((P[0]-x0)*dx+(P[1]-y0)*dy)/(L*L),0.0,1.0)
        qx=x0+u*dx;qy=y0+u*dy
        d=math.hypot(P[0]-qx,P[1]-qy)
        if best is None or d<best[0]: best=(d,acc+u*L)
        acc+=L
    s=best[1]+la;acc=0.0
    for i in range(len(path)-1):
        x0,y0=path[i];x1,y1=path[i+1]
        L=math.hypot(x1-x0,y1-y0)
        if acc+L>=s:
            u=(s-acc)/L
            return (x0+u*(x1-x0),y0+u*(y1-y0)),best[0]
        acc+=L
    return path[-1],best[0]
def control(obs):
    t=obs['t']; mo=obs['motion']; v=mo['v_mps']; sd=obs['steer_deg']
    if st['lt'] is not None:
        h=t-st['lt']
        if 0<h<1:
            th=st['th']
            st['x']+=v*math.cos(th)*h; st['y']+=v*math.sin(th)*h
            st['th']=wrap(th+v*math.tan(math.radians(sd))/L1*h)
            if v<0: st['od']+=-v*h
            else: st['fo']+=v*h
    st['lt']=t
    rig=obs['rig']; hitch=obs['hitch_deg']; status=obs.get('status')
    look=160
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('dist_m') is not None:
            ex,ey=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
            bx,by=tw(ex+d*math.cos(b),ey+d*math.sin(b))
            w=clamp(0.3/max(d,1.0),0.03,0.3)
            st['bay'][0]+=w*(bx-st['bay'][0]); st['bay'][1]+=w*(by-st['bay'][1])
    except Exception:
        pass
    rx,ry=rig['trailer_rear']; hx,hy=rig['hitch']
    try:
        vf=float(rig.get('vehicle_front',1.5)); vhw=float(rig.get('vehicle_half_width',0.525)); thw=float(rig.get('trailer_half_width',0.475))
    except Exception:
        vf=1.5; vhw=0.525; thw=0.475
    ux,uy=hx-rx,hy-ry; n=math.hypot(ux,uy) or 1.0; ux/=n; uy/=n
    dv=9.0; dtr=9.0; cp=None
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]) or []:
                px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
                dd=boxd(px,py,vf-1.8,vf,vhw)
                if dd<dv: dv=dd; cp=(px,py)
                qx=px-rx; qy=py-ry
                a=qx*ux+qy*uy; c=-qx*uy+qy*ux
                dtr=min(dtr,boxd(a,c,0.0,1.0,thw))
        except Exception:
            pass
    if st['ph']=='fwd':
        if st['fo']<0.6:
            return {'steer_deg':20.0,'speed_mps':0.35,'look_deg':look}
        st['ph']='go'; print('fwd done t=%.1f h=%.1f'%(t,hitch))
    if st['ph']=='unjk':
        if abs(hitch)<25: st['ph']='go'
        else: return {'steer_deg':clamp(-0.7*hitch,-30,30),'speed_mps':0.4,'look_deg':look}
    if abs(hitch)>55 or status=='JACKKNIFED':
        st['ph']='unjk'; print('unjk t=%.1f h=%.1f'%(t,hitch))
        return {'steer_deg':clamp(-0.7*hitch,-30,30),'speed_mps':0.4,'look_deg':look}
    Rx,Ry=tw(rx,ry)
    psi=st['th']+math.radians(rig['trailer_heading_deg'])
    bd=wrap(psi+math.pi)
    Ax,Ay=Rx-0.45*math.cos(bd),Ry-0.45*math.sin(bd)
    bx=clamp(st['bay'][0],-2.6,-1.8)
    path=[(-1.3,0.3),(-1.8,2.4),(bx,4.6),(bx,14.0)]
    (gx,gy),cte=lookpt(path,(Ax,Ay),1.4)
    alpha=math.atan2(gy-Ay,gx-Ax)
    eh=math.degrees(wrap(alpha-bd))
    ht=clamp(-1.2*eh,-38,38)
    steer=clamp(ff(ht)+2.5*(hitch-ht),-45,45)
    spd=-0.25
    if dv<0.15 or dtr<0.15 or abs(hitch-ht)>20: spd=-0.15
    if t-st['pr']>1.5:
        st['pr']=t
        print('t=%.1f A=(%.2f,%.2f) bd=%.0f h=%.1f ht=%.1f st=%.0f dv=%.2f dt=%.2f cte=%.2f bay=(%.2f,%.2f) cp=%s'%(t,Ax,Ay,math.degrees(bd),hitch,ht,steer,dv,dtr,cte,st['bay'][0],st['bay'][1],cp))
    return {'steer_deg':steer,'speed_mps':spd,'look_deg':look}

