    if st['lt'] is not None: h=max(0.0,min(1.0,t-st['lt']))
    st['lt']=t
    st['od']+=abs(v)*h
    if st['done']:
        if not st['woke']:
            st['woke']=True
            print('freed with cand %s od=%.2f status=%s hitch=%.1f'%(C[st['i']],st['od'],obs.get('status'),obs['hitch_deg']))
            try: wake('freed, moved %.2f m with %s'%(st['od'],C[st['i']]))
            except Exception: pass
        return {'steer_deg':obs['steer_deg'],'speed_mps':0.0,'look_deg':-150}
    s,sp=C[st['i']]
    if hold<=0 and abs(v)<0.02 and abs(obs['steer_deg']-s)<3: st['still']+=h
    if st['od']>=0.22 or (st['od']>0.12 and obs.get('status')!='PINNED'):
        st['done']=True
        return {'steer_deg':s,'speed_mps':0.0,'look_deg':-150}
