C=[(0.0,0.3),(25.0,0.3),(-45.0,0.3),(45.0,-0.2),(-45.0,-0.2),(0.0,-0.2)]
st={'i':0,'still':0.0,'od':0.0,'lt':None,'done':False,'woke':False}
def control(obs):
    t=obs['t']; mo=obs['motion']; v=mo['v_mps']; hold=mo.get('hold_s',0) or 0
    h=0.0
    if st['lt'] is not None: h=max(0.0,min(1.0,t-st['lt']))
    st['lt']=t
    st['od']+=abs(v)*h
    s,sp=C[st['i']]
    if st['done']:
        if not st['woke']:
            st['woke']=True
            print('freed cand %s od=%.2f status=%s hitch=%.1f'%(C[st['i']],st['od'],obs.get('status'),obs['hitch_deg']))
            try: wake('freed %.2f m with %s'%(st['od'],C[st['i']]))
            except Exception: pass
        return {'steer_deg':obs['steer_deg'],'speed_mps':0.0,'look_deg':-60}
    if hold<=0 and abs(v)<0.02 and abs(obs['steer_deg']-s)<3: st['still']+=h
    lim=0.35 if sp>0 else 0.2
    if st['od']>=lim:
        st['done']=True
        return {'steer_deg':s,'speed_mps':0.0,'look_deg':-60}
    if st['still']>1.2:
        print('cand %s blocked t=%.1f'%(C[st['i']],t))
        st['i']=(st['i']+1)%len(C); st['still']=0.0; st['od']=0.0
        s,sp=C[st['i']]
    return {'steer_deg':s,'speed_mps':sp,'look_deg':-60}

