import math
L=3.9; D=10.2
S={'x':0.0,'y':0.0,'p':0.0,'tick':0,'hd':0.0,'fwd':False,'last':0}
PTS={}
COR={}
TGT=[None]
SEQ=[(-41,8),(53,3),(-41,8),(-72,3)]
def wrap(a):
    return (a+180.0)%360.0-180.0
def tow(px,py):
    c=math.cos(S['p']); s=math.sin(S['p'])
    return (S['x']+px*c-py*s, S['y']+px*s+py*c)
def gaze_for(t):
    tot=sum(n for g,n in SEQ); k=t%tot
    for g,n in SEQ:
        if k<n: return g
        k-=n
    return -41
def control(obs):
    dt=obs.get('dt',0.1) or 0.1
    m=obs.get('motion',{})
    v=m.get('v_mps',0.0) or 0.0
    sd=obs.get('steer_deg',0.0) or 0.0
    S['p']+=v*math.tan(math.radians(sd))/L*dt
    S['x']+=v*math.cos(S['p'])*dt; S['y']+=v*math.sin(S['p'])*dt
    S['tick']+=1
    h=obs.get('hitch_deg',0.0) or 0.0
    rig=obs['rig']
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not isinstance(vw,dict): continue
        try:
            ox,oy=vw['origin']
        except Exception:
            continue
        for w in vw.get('walls') or []:
            try:
                b,d=float(w[0]),float(w[1])
            except Exception:
                continue
            if d>12.0: continue
            X,Y=tow(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b)))
            PTS[(round(X/0.3),round(Y/0.3))]=(X,Y)
        for c in vw.get('target_corners') or []:
            try:
                b,d=float(c[0]),float(c[1])
            except Exception:
                continue
            if d>25: continue
            X,Y=tow(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b)))
            k=None
            for kk,(cx,cy,n) in COR.items():
                if math.hypot(cx-X,cy-Y)<1.0: k=kk; break
            if k is None:
                COR[len(COR)+1000*S['tick']]=(X,Y,1)
            else:
                cx,cy,n=COR[k]; n2=min(n,20)
                COR[k]=((cx*n2+X)/(n2+1),(cy*n2+Y)/(n2+1),n+1)
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        TGT[0]=tow(ex+d*math.cos(b),ey+d*math.sin(b))
    rx,ry=tow(rig['trailer_rear'][0],rig['trailer_rear'][1])
    th=rig.get('trailer_heading_deg',-h)
    back=S['p']+math.radians(th+180.0)
    loc=[p for p in PTS.values() if abs(p[0]-rx)<22 and abs(p[1]-ry)<22]
    rc=1.8; cap=18.0
    offs=list(range(-66,67,3)); fl=[]
    for o in offs:
        a=back+math.radians(o); ux=math.cos(a); uy=math.sin(a); f=25.0
        for (px,py) in loc:
            dx=px-rx; dy=py-ry; al=dx*ux+dy*uy
            if al<0.3 or al>f: continue
            if abs(dx*uy-dy*ux)<rc: f=al
        fl.append(f)
    n=len(offs)
    fs=[min(fl[max(0,i-1)],fl[i],fl[min(n-1,i+1)]) for i in range(n)]
    sc=[min(fs[i],cap)-0.03*abs(offs[i]) for i in range(n)]
    bi=max(range(n),key=lambda i:sc[i])
    lo=bi; hi=bi
    while lo>0 and sc[lo-1]>=sc[bi]-1.0: lo-=1
    while hi<n-1 and sc[hi+1]>=sc[bi]-1.0: hi+=1
    o=(offs[lo]+offs[hi])/2.0
    mode='gap'
    def freeto(ax,ay):
        dd=math.hypot(ax-rx,ay-ry)
        a=math.atan2(ay-ry,ax-rx); ux=math.cos(a); uy=math.sin(a)
        for (px,py) in loc:
            dx=px-rx; dy=py-ry; al=dx*ux+dy*uy
            if 0.3<al<dd-1.0 and abs(dx*uy-dy*ux)<1.4: return False
        return True
    good=[c for c in COR.values() if c[2]>=2]
    aim=None
    if len(good)>=3:
        cx=sum(c[0] for c in good)/len(good); cy=sum(c[1] for c in good)/len(good)
        if math.hypot(cx-rx,cy-ry)<25:
            sxx=sum((c[0]-cx)**2 for c in good); syy=sum((c[1]-cy)**2 for c in good); sxy=sum((c[0]-cx)*(c[1]-cy) for c in good)
            ang=0.5*math.atan2(2*sxy,sxx-syy); ax_=math.cos(ang); ay_=math.sin(ang)
            if (cx-rx)*ax_+(cy-ry)*ay_<0: ax_=-ax_; ay_=-ay_
            s=(rx-cx)*ax_+(ry-cy)*ay_
            s2=max(s+6.0,2.0)
            aim=(cx+ax_*s2,cy+ay_*s2); mode='bay'
    if aim is None and TGT[0] is not None and math.hypot(TGT[0][0]-rx,TGT[0][1]-ry)<20:
        aim=TGT[0]; mode='tgt'
    if aim is not None and (mode=='bay' or freeto(aim[0],aim[1])):
        o=wrap(math.degrees(math.atan2(aim[1]-ry,aim[0]-rx)-back))
        o=max(-70,min(70,o))
    else:
        mode='gap'
    hdes=max(-35.0,min(35.0,-1.5*o))
    step=15.0*dt
    S['hd']+=max(-step,min(step,hdes-S['hd']))
    hd=S['hd']
    look=gaze_for(S['tick'])
    if S['fwd']:
        if abs(h)<12:
            S['fwd']=False
        return (0.0,1.0,look)
    if abs(h)>60:
        S['fwd']=True
        wake('hitch %.0f, pulling forward'%h)
        return (0.0,1.0,look)
    eq=math.degrees(math.atan(L/D*math.sin(math.radians(h))))
    st=eq+1.6*(h-hd)
    st=max(-42.0,min(42.0,st))
    ci=offs.index(min(offs,key=lambda q:abs(q-o))) if True else 0
    sp=-0.9
    if abs(h-hd)>15 or fs[ci]<5: sp=-0.6
    if S['tick']-S['last']>=20:
        S['last']=S['tick']
        print('t%.0f h%.0f hd%.0f o%.0f f%.1f st%.0f %s n%d c%d'%(obs.get('t',0),h,hd,o,fs[ci],st,mode,len(PTS),len(good)))
    return (st,sp,look)

